  </div>

  <!--
    Shown while displayTable is false. init() (which sets displayTable) is
    deferred past the tab switch, so this branch covers the prep window: show a
    loader while lineItemsloading is true, and the "no items" message only once
    loading has finished. (Same pattern as PoTable / LineItemTable.)
  -->
  <div v-else class="ai-table-loading-wrapper full-width">
    <q-inner-loading :showing="lineItemsloading" color="primary">
      <q-spinner-hourglass color="primary" size="4em" />
    </q-inner-loading>
    <q-markup-table v-if="!lineItemsloading" class="full-width">
      <thead>
        <tr class="highlighted-back">
