<script lang="ts">

import { storeToRefs } from 'pinia';
import { objLen } from 'src/utils/general';
import { defineComponent, ref } from 'vue';
import TableResizeHandle from 'src/single-component/TableResizeHandle.vue';
import helperUtil from 'src/utils/helperUtil';
import Charges from 'src/components/Charges.vue';
import { type dynamicObj, $ } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import documentUtil from 'src/utils/documentUtil';
import { uid } from 'quasar';
import docTablesUtil from 'src/utils/docTablesUtil';
import ColorGenerator from 'src/utils/ColorGenerator';
import {
  orgApiService,
  orgPreferenceApiService,
  userApiService,
} from 'src/services';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import resizableGridUtil from 'src/utils/resizableGridUtil';

import amountConversionHelper from 'src/utils/amountConversionHelper';
import { isUndefinedOrNull } from 'src/utils/general';
import {
  tableRowIdPreFix,
  CONSTANTS,
  AI_table_extraction_setting,
  charges_table_extraction,
} from 'src/constants';
import {
  useSettingStore,
  useDocLockStore,
  useDocumentStore,
  useLineItemStore,
  useFormBuilderStore,
} from 'src/store/main';
import { nextTick } from 'vue';
import { aiTableApiService } from 'src/services';
import csvExportUtil from 'src/utils/csvExportUtil';
import { ApiExceptions } from 'src/exceptions/index';

import TableInputField from './components/TableInputField.vue';
import { notify } from 'src/components/notifications/notify';
import tableExtractionMixin from 'src/mixins/tableExtractionMixin';
import ColumnOrigin from './components/ExtractedTableTabPanels/ColumnOrigin.vue';
import ExtractOrigin from './components/ExtractedTableTabPanels/ExtractOrigin.vue';
import CreateCustomColumn from 'src/pages/Settings/customColumns/Create-Custom-Column.vue';
import NonMappedColumnsSelection from './components/AIExtractedTable/NonMappedColumnsSelection.vue';
import ConfirmRemapDialog from 'src/components/ConfirmRemapDialog.vue';

export default defineComponent({
  name: 'AIExtractedTable',
  components: {

    ConfirmRemapDialog,
    CreateCustomColumn,
    ColumnOrigin,
    NonMappedColumnsSelection,
    Charges,
    ExtractOrigin,
    TableInputField,
    TableResizeHandle,
  },
  mixins: [
    helperMixin, ColorGenerator,
    resizableGridUtil,
    documentUtil,
    helperUtil,
    docTablesUtil,
    displayFieldLabel,
    amountConversionHelper,
    csvExportUtil,
    tableExtractionMixin,
  ],
  emits: [
    'updateExtractionDataForSave',
    'setTableRowCorrdinates',
    'loadNewPageImage',
    'updateModel',
  ],
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.init();
        }
      },
    },
  },
  computed: {
    hasSettingDisabled: function (): boolean {
      return Boolean(this.doc_loaded && !this.setting_flag);
    },
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    this.destoryAndRest(this.tableId);
    next();
  },
  data() {
    return {
      dropdownColumns: [] as any,
      rows_to_delete: [] as any,
      po_dragging: false,
      dragging_data: {} as any,
      coveredLineItem: [] as any,
      validation_done: true,
      connected_line_item: '',
      renderKey: 0,
      is_po_view: false,
      confirmReformate: ref(false),

      po_connected_line_items: {} as { [k: string]: any },
      is_auto_filled_color: '#c2dba6',
      is_missing_color: '#eed69e',
      tableObj: {} as any,
      AI_table_extraction_setting,
      costingElementIdPreFix: CONSTANTS.costingElementIdPreFix,
      isChargesModule: ref(false),
    };
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    // Defer heavy init() past the next paint so the tab indicator switches
    // instantly; the lineItemsloading overlay covers the wait. (See PoTable.)
    requestAnimationFrame(() => {
      setTimeout(() => {
        this.init();
      }, 120);
    });
    document.addEventListener('delete_table', this.deleteTable);
    document.addEventListener('add_new_row', this.createNewRow);
    document.addEventListener('add_new_empty_row', this.createNewEmptyRow);
    document.addEventListener('prepare_rows', this.reRenderTable);
    document.addEventListener('display_fields_errors', this.reRenderTable);
    document.addEventListener('add_ai_new_column', this.addNewCustomColumn);
    document.addEventListener('custom_column_create', this.customColumnCreated);
     
    document.addEventListener('restore_delete_column', async (event) => {
      await this.restoreDeleteColumn(event);
    });
    document.addEventListener(
      'add_non_mapped_columns',
      this.addNonMappedColumns,
    );
    document.addEventListener(
      'show_non_mapped_columns_dialog',
      this.displayNonMappedColumnsDialog,
    );

    // make new event for action show and hide map column
    document.addEventListener('render_map_coulums', this.renderShowMapCoulums);
    (<any>window).ait = this;

    nextTick(() => {
      let fieldEl: HTMLElement | null = document!.querySelector(
        '.' + 'table_' + this.fieldName,
      );
      if (fieldEl) {
        fieldEl.addEventListener(
          'focus_first_row_ai_table',
          this.focusFirstRowColumn,
        );
        fieldEl.addEventListener(
          'trigger_add_row_ai_table',
          this.createNewEmptyRow,
        );
      }
    });
  },
  unmounted: function () {
    document.removeEventListener('delete_table', this.deleteTable);
    document.removeEventListener('add_new_row', this.createNewRow);
    document.removeEventListener('add_new_empty_row', this.createNewEmptyRow);
    document.removeEventListener('prepare_rows', this.reRenderTable);
    document.removeEventListener('display_fields_errors', this.reRenderTable);
    document.removeEventListener('add_ai_new_column', this.addNewCustomColumn);
    document.removeEventListener(
      'custom_column_create',
      this.customColumnCreated,
    );

     
    document.removeEventListener('restore_delete_column', async (event) => {
      await this.restoreDeleteColumn(event);
    });

    document.removeEventListener(
      'add_non_mapped_columns',
      this.addNonMappedColumns,
    );
    document.removeEventListener(
      'show_non_mapped_columns_dialog',
      this.displayNonMappedColumnsDialog,
    );

    // make new event for action show and hide map column
    document.removeEventListener('render_map_coulums', this.renderShowMapCoulums);

    let fieldEl: HTMLElement | null = document!.querySelector('.' + 'table_' + this.fieldName);
    if (fieldEl) {
      fieldEl.removeEventListener('focus_first_row_ai_table', this.focusFirstRowColumn);
      fieldEl.removeEventListener('trigger_add_row_ai_table', this.createNewEmptyRow);
    }
  },
  methods: {
    async init() {
      this.checkSetting();
      if (
        this.isFormBuilderMode ||
        this.doc_loaded === false ||
        this.record === null ||
        this.record === undefined ||
        this.setting_flag === false ||
        !this.has_ai_table ||
        this.record.tables === null ||
        this.record.tables.length == 0 ||
        this.displayTable == true
      ) {
        return;
      }

      this.displayTable = true;
      for (let table of this.record.tables) {
        // right now we are only supporting one table
        this.tableObj = table;
        break;
      }

      await this.startSettingsFetch();
      this.lineItemDataLoaded();

      if (this.user_settings[charges_table_extraction]) {
        this.isChargesModule = true;
      }
    },

    // Abstract method implementations for tableExtractionMixin
    getColumnIdentifier(column: any) {
      return column.original_name != null && column.original_name != undefined ? String(column.original_name) : '';
    },
    getHeaderIdentifier(header: any) {
      return header.original_name;
    },
    storeIdentifierInMapping(identifier: any) {
      return identifier;
    },
    // Override setTableData to also set AI-specific properties
    setTableData(data: any) {
      this.tableObj = data;
      this.ai_prompt = this.tableObj.ai_prompt;
      if (this.tableObj.hasOwnProperty('ai_tags')) {
        this.ai_tags = this.tableObj.ai_tags;
      }
    },

    checkSetting() {
      if (this.isFormBuilderMode) {
        return;
      }
      this.setting_flag = false;
      if (this.user_settings[this.AI_table_extraction_setting]) {
        this.setting_flag =
          this.user_settings[this.AI_table_extraction_setting];
      }
    },

    async get_org_pref(key: string) {
      let flag = false;
      try {
        let data = {
          main_key: key,
        };

        const response = await orgPreferenceApiService.getOrgPref(data);

        if (response.success === false) {
          throw response;
        }

        flag = response;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }

      return flag;
    },

    lineItemDataLoaded() {
      this.resetRows();
      this.refactorApiData();
      // Clear the loader only after the rows have been built (refactorApiData),
      // not before — otherwise the overlay hides over a still-empty table.
      this.lineItemsloading = false;
    },

    inputKeyDown(event: any) {
      if (this.training_mode) {
        event.preventDefault();
        event.target.blur();
        notify.error(this.$t('manual_change'));
        return;
      }
    },
    refactorApiData() {
      this.resetFormatSettings();
      this.setFormatOptions();
      this.setAdvSettings();
      this.prepareTableLayoutObj();
      this.prepareTableColumn();
      this.prepareTableRowsAndRowObj();
      // prepare line Item headers
      this.sortTableColumn();
      this.validateLineItemColumns();
      this.prepareDisabledCstmColumnsList();
      this.preparePrompt();

      this.resetAndReInitColumnResize('table_' + this.fieldName);
    },

    preparePrompt() {
      this.ai_prompt = '';
      this.ai_tags = [];

      if (!this.tableObj) {
        return;
      }

      if (this.tableObj.hasOwnProperty('ai_prompt')) {
        this.ai_prompt = this.tableObj.ai_prompt;
      }

      if (this.tableObj.hasOwnProperty('ai_tags')) {
        this.ai_tags = this.tableObj.ai_tags;
      }
    },

    prepareTableRowsAndRowObj() {
      this.docStore.confirmationForPoConnectionReset = true;
      this.tableRows = [];
      this.lineDataObj = [];
      let lineDataTemp = {} as dynamicObj;
      this.lineItemsErrorsRaw = {};
      this.tableRowsLocationsMap.clear();
      // logInfo('prepareTableRowsAndRowObj');
      // formate table rows data
      if (
        !this.tableObj ||
        !this.tableObj.hasOwnProperty('rows') ||
        this.tableObj.rows.length == 0
      ) {
        return;
      }

      //logInfo('prepareTableRowsAndRowObj 2');
      let id = this.tableObj.rows[0].id;

      // logInfo('first id', JSON.parse(JSON.stringify(this.tableObj.rows[0])) );
      //  logInfo('first id', JSON.parse(JSON.stringify(this.tableObj.rows[0])) );

      Array.from(this.tableObj.rows).forEach((row: any) => {
        if (row.is_deleted === false) {
          let newRow: dynamicObj = {};
          // Clone 'Data' deeply (single clone for the whole row; the per-column
          // handling below reuses these already-cloned objects instead of
          // cloning each column a second time).
          const clonedRow = JSON.parse(JSON.stringify(row));
          const clonedColumns = clonedRow.columns || [];
          lineDataTemp[row.id] = clonedRow;
          lineDataTemp[row.id].show_menu = false;
          // prepare row location list to get on indexes
          lineDataTemp[row.id].locations_list = [] as any;
          if (row.locations_list) {
            Array.from(row.locations_list).forEach((location: any) => {
              lineDataTemp[row.id].locations_list['page_' + location.page] =
                location;

              // store only first rows of all the pages so that we can highlite them on page selection
              if (!this.tableRowsLocationsMap.has('page_' + location.page)) {
                this.tableRowsLocationsMap.set('page_' + location.page, row.id);
              }
            });
          }

          delete lineDataTemp[row.id].columns;
          lineDataTemp[row.id]['columns'] = [] as any;
          Array.from(clonedColumns).forEach((clonedColumn: any, idx: number) => {
            const column = row.columns[idx];
            if (lineDataTemp[row.id].columns[column.name]) {
              return;
            }
            lineDataTemp[row.id].columns[column.name] = clonedColumn;

            // prepare column location list to get on indexes
            lineDataTemp[row.id].columns[column.name].locations_list =
              [] as any;

            if (column.locations_list) {
              Array.from(column.locations_list).forEach((location: any) => {
                lineDataTemp[row.id].columns[column.name].locations_list[
                  'page_' + location.page
                ] = location;
              });
            }

            //prepare line item Table rows
            if (row.id == id) {
              //logInfo('NEW_ID',column.name, column.formatted_value);
            }
            if (isUndefinedOrNull(column.formatted_value)) {
              column.formatted_value = '';
            }

            newRow[column.name] = column.formatted_value;
            this.prepareMapOfColumnHavingData(column);
          });
          // add extra column in the row
          this.addExtraColumnsInRow(lineDataTemp, newRow, row.id);
          // column for buttons
          newRow['id'] = row.id;

          if (row.id == id) {
            //logInfo('NEW_ID',JSON.parse(JSON.stringify(newRow)));
          }

          this.tableRows.push(newRow);
          this.setRowErrors(row);
        }
      });
      Object.assign(this.lineDataObj, lineDataTemp);
      this.addExtraColumnsInExportJson();
    },
    addExtraColumnsInExportJson() {
      if (this.layoutExtraColumns.length === 0) {
        return;
      }
      for (const row of this.tableObj.rows) {
        // Build a fresh column object per row (do NOT share one reference across
        // rows, or every row would mutate the same object) and append them in a
        // single push instead of one reactive push per column.
        const newColumns = this.layoutExtraColumns.map((colName: string) => ({
          name: colName,
          value: '',
          content: '',
          locations: [],
          locations_list: [],
          formatted_value: '',
          is_extra_column: true,
        }));
        row.columns.push(...newColumns);
      }
    },
    prepareTableLayoutObj() {
      // remove duplicate
      this.tags_options = [];
      this.dropdownColumns = [];
      let duplicate_columns = {} as dynamicObj;
      this.lineItemLayout = {} as dynamicObj;
      this.initStandardColumns();

      // logInfo('prepareTableLayoutObj', this.tableObj)
      if (!(this.tableObj && this.tableObj.hasOwnProperty('layout'))) {
        return;
      }

      Array.from(this.tableObj.layout).forEach((column: any) => {
        if (
          !duplicate_columns.hasOwnProperty(column.column_name) &&
          column.is_hidden == false
        ) {
          duplicate_columns[column.column_name] = true;

          // prepare Coloum layout
          column['lbl_to_display'] = this.getLabelToDisplay(column);
          this.lineItemLayout[column.column_name] = column;

          this.addStandardColumns(column);

          // prepare Coloum Dropdown
          this.dropdownColumns.push({
            header: column.lbl_to_display,
            techName: column.column_name,
          });
          this.tags_options.push({
            label: column.lbl_to_display,
            value: column.column_name,
          });
        }
      });

      this.tags_filtered_options = JSON.parse(
        JSON.stringify(this.tags_options),
      );
      this.sortMappingColumns();
    },
    prepareTableColumn() {
      this.tableColumns = [];
      let tempColumnArray: any = {};
      this.layoutExtraColumns = [];

      if (
        !(
          this.tableObj &&
          this.tableObj.hasOwnProperty('rows') &&
          this.tableObj.rows.length > 0
        )
      ) {
        return;
      }


      // for column preparation there will be couple of steps
      // 1. prepare columns from table 0 and row 0
      // 2. columns that do not have data will be move to the end
      // 3. then check table layout for extra columns.
      // 4. before save and export check if table extra columns do not have data then remove those columns to optimize the JSON

      // logInfo('prepareTableColumn 2', this.tableObj.rows)

      const row = this.tableObj.rows[0];
      if (!row) {
        return;
      }

      let tempLineItemLayout = JSON.parse(JSON.stringify(this.lineItemLayout));
      Array.from(row.columns).forEach((column: any) => {
        let allowed = this.isColumnHidden(row, column);
        if (allowed && column.name != 'id') {
          // Add only those column that are in the layout
          let label = column.name;
          let column_type = 'string';
          let isRequired = '';
          let alwaysVisible = '';

          if (this.lineItemLayout.hasOwnProperty(column.name)) {
            label = this.lineItemLayout[column.name].lbl_to_display;
            if (
              this.lineItemLayout[column.name].hasOwnProperty('column_type')
            ) {
              column_type = this.lineItemLayout[column.name].column_type;
              isRequired = this.lineItemLayout[column.name].is_required;
              alwaysVisible = this.lineItemLayout[column.name].always_visible;
            }
            delete tempLineItemLayout[column.name];
          }

          let org_index = '';
          if (column.org_index != null && column.org_index != undefined) {
            org_index = String(column.org_index);
          }

          let columnItem = {
            name: column.name,
            field: column.name,
            align: 'left',
            label: label,
            is_mapped: column.is_mapped ? column.is_mapped : false,
            column_type: column_type,
            org_index: org_index,
            col_origin: 'auto',
            extract_from: '',
            is_required: isRequired,
            always_visible: alwaysVisible,
            original_name: this.getOrignalColumnName(column),
            is_extra_column: column.hasOwnProperty('is_extra_column')
              ? column.is_extra_column
              : false,
          };

          columnItem.col_origin = this.getColumnOrigin(
            this.tableObj,
            column.name,
          );
          columnItem.extract_from = this.getExtractOrigin(
            this.tableObj,
            column.name,
          );

          const is_non_mapped_allowed = columnItem.is_mapped || (!this.remove_unmapped_columns && !columnItem.is_mapped);

          if (
            column.hasOwnProperty('org_index') &&
            column.org_index != null &&
            is_non_mapped_allowed
          ) {
            this.tableColumns.push(columnItem);
          } else {
            tempColumnArray[column.name] = columnItem;
          }
        } else {
           delete tempLineItemLayout[column.name];
        }
      });

      // remove column without org_index / extractable-column-text
      for (let [key, value] of Object.entries(tempColumnArray)) {
        const column = value as dynamicObj;
        if (
          (column.hasOwnProperty('is_extra_column') &&
            column.is_extra_column === true) ||
          column.always_visible ||
          column.is_required
        ) {
          this.tableColumns.push(column);
        }
      }
      // at the end add extra column in the table that are in the layout
      for (let index in tempLineItemLayout) {
        const column = tempLineItemLayout[index];

        // org_index 0 is a valid original index (the first extracted column),
        // so it must not be filtered out by a truthiness check. Only a
        // missing/null index or the '' sentinel means "no original index" —
        // same rule as hasOriginalIndex() and as the guards above.
        if (
          !column.hasOwnProperty('org_index') ||
          column.org_index == null ||
          column.org_index === ''
        ) {
          continue;
        }

        let allowed = !this.isCustomColumnHidden(column.column_name);
        if (!allowed) {
          delete tempLineItemLayout[column.column_name];
          continue;
        }

        const is_non_mapped_allowed =
          column.is_mapped ||
          (!this.remove_unmapped_columns && !column.is_mapped);
        if (!is_non_mapped_allowed) {
          delete tempLineItemLayout[column.column_name];
          continue;
        }

        let column_type = 'string';
        if (
          this.lineItemLayout.hasOwnProperty(column.column_name) &&
          this.lineItemLayout[column.column_name].hasOwnProperty('column_type')
        ) {
          column_type = this.lineItemLayout[column.column_name].column_type;
        }

        let columnItem = {
          name: column.column_name,
          field: column.column_name,
          align: 'left',
          label: column.lbl_to_display,
          is_mapped: column.is_mapped ? column.is_mapped : false,
          column_type: column_type,
          org_index: null,
          is_extra_column: column.hasOwnProperty('is_extra_column')
            ? column.is_extra_column
            : false,
          col_origin: 'auto',
          extract_from: '',
          original_name: this.getOrignalColumnName(column),
        };

        columnItem.col_origin = this.getColumnOrigin(
          this.tableObj,
          column.column_name,
        );
        columnItem.col_origin = this.getExtractOrigin(
          this.tableObj,
          column.column_name,
        );
        this.tableColumns.push(Object.assign({}, columnItem));
        this.layoutExtraColumns.push(column.column_name);
      }
    },

    getOrignalColumnName(column: any) {
      if (
        !column.hasOwnProperty('original_name') ||
        isUndefinedOrNull(column.original_name)
      ) {
        return '';
      }
      return String(column.original_name);
    },

    // function for restore table column
    async restoreDeleteColumn(e: any) {
      this.columns_to_hide = '';

      let restore_table_columns = false;
      if (e && e.detail && e.detail.restore_table_columns) {
        restore_table_columns = e.detail.restore_table_columns;
      }

      await this.requestReformate(restore_table_columns);
      this.dispatchEventToSaveTableChanges();
      this.reRenderTable();
      return;
    },
    editColumnData(e: any, columnName: any, rowId: string) {
      if (this.lineDataObj[rowId].hasOwnProperty('custom_row')) {
        return;
      }

      if (this.isRowMode === true) {
        let waitTime = 10;
        // clear old selection
        this.clearOldSelection();
        if (e.target.closest('label')) {
          (e.target.closest('label') as HTMLElement).classList.add(
            'active-border-2px',
          );
        }

        let currentColumnObj: any;
        currentColumnObj = this.lineDataObj[rowId].columns[columnName];

        let columnSelection = true;

        if (currentColumnObj && currentColumnObj.locations_list) {
          let locationList = currentColumnObj.locations_list;

          if (locationList.hasOwnProperty('page_' + this.currentPageNo)) {
            columnSelection = false;
          } else if (Object.entries(locationList).length != 0) {
            waitTime = 200;
            for (const key in locationList) {
              columnSelection = false;
              let pageNo = +locationList[key].page - 1;
              this.$emit('loadNewPageImage', pageNo);
              break;
            }
          } else {
            this.loadAppropriatePage(rowId);
          }
        }

        // wait until the new page image is loaded
        setTimeout(() => {
          if (columnSelection === false) {
            let detailObj = { rowId: rowId, columnName: columnName };
            this.getTableRowsAreas({ detail: detailObj });

            // wait until the table areas are prepared
            setTimeout(() => {
              let selectedArea: HTMLElement | null = $(
                '#' + 'draw_' + columnName,
              );
              if (selectedArea) {
                (
                  selectedArea.querySelector(
                    '.select-areas--outline',
                  ) as HTMLElement
                ).style.opacity = '0';

                let selection = selectedArea.querySelector(
                  '.select-areas--background_area',
                ) as HTMLElement;
                selection.style.border = '2px';
                selection.style.borderStyle = 'solid';
                selection.style.borderColor = '#8800ff';

                this.oldSelectedColumnName = columnName;

                this.scrollInToViewCenter(selection);

                // remove existing correction dialog
                this.removeExistingConfirmationOverlays();

                if (
                  currentColumnObj &&
                  this.addExtractionMethodClass(currentColumnObj) !== ''
                ) {
                  setTimeout(() => {
                    let column_value: string =
                      e.target.closest('td').dataset.columnValue;
                    let score_description: string =
                      e.target.closest('td').dataset.scoreDescription;
                    let detailObj = {
                      value: column_value,
                      score: score_description,
                      selection: selection,
                    };

                    const event = new CustomEvent('prepare_overlay', {
                      detail: detailObj,
                    });
                    document.dispatchEvent(event);
                  }, 20);
                }
              }
            }, waitTime);
          } else {
            // if no area for the column let the user select one.
            this.showNotification(this.$t('SELECT_AREA'));

            let detailObj = {
              rowId: rowId,
              columnName: columnName,
              onlySelectedRow: true,
            };
            this.getTableRowsAreas({ detail: detailObj });

            // wait until the table areas are prepared
            setTimeout(() => {
              const event = new CustomEvent('enable_column_selection', {
                detail: rowId,
              });
              document.dispatchEvent(event);
            }, 10);
          }
        }, 10);
      } else {
        this.loadAppropriatePage(rowId);
        setTimeout(() => {
          let detailObj = {
            rowId: rowId,
            columnName: columnName,
            onlySelectedRow: true,
          };
          this.drawSelectedRow({ detail: detailObj });

          setTimeout(() => {
            let selectedArea: HTMLElement | null = $('#' + 'draw_' + rowId);
            if (selectedArea) {
              this.oldSelectedColumnName = columnName;
              let selection = selectedArea.querySelector(
                '.select-areas--background_area',
              ) as HTMLElement;
              this.scrollInToViewCenter(selection);
            }
          }, 40);
        }, 100);
      }
    },
    createNewEmptyRow() {
      let newRowJson = this.createRowJson();

      newRowJson.columns.forEach((column: { original_content?: string }) => {
        delete column.original_content;
      });

      this.tableObj.rows.splice(this.tableRows.length, 0, newRowJson);
      this.prepareTableRowsAndRowObj();
    },
    createRowJson(): any {
      let newRowJson = JSON.parse(JSON.stringify(this.tableObj.rows[0]));
      newRowJson.id = uid();
      newRowJson.ids = [];
      newRowJson.content = '';
      newRowJson.locations = [];
      newRowJson.locations_list = [];
      newRowJson.is_deleted = false;
      newRowJson.messages = [];
      newRowJson.custom_row = true;

      Array.from(newRowJson.columns).forEach(
        (column: any, columnIndex: any) => {
          column.content = '';
          column.locations = [];
          column.locations_list = [];
          column.value = '';
          column.formatted_value = [];
        },
      );

      return newRowJson;
    },
    highliteFirstRowOfCurrentPage() {
      if (this.tableRowsLocationsMap.has('page_' + this.currentPageNo)) {
        const rowId = this.tableRowsLocationsMap.get(
          'page_' + this.currentPageNo,
        );
        const rowElement = $('#' + tableRowIdPreFix + rowId) as HTMLElement;
        if (rowElement) {
          this.scrollInToViewStart(rowElement);
          setTimeout(() => {
            rowElement.classList.add('light-grey-with-effect');
            setTimeout(() => {
              rowElement.classList.remove('light-grey-with-effect');
            }, 1400);
          }, 500);
        }
      }
    },
    getRowIdPrefix() {
      return tableRowIdPreFix;
    },
    getColumnClass(columnStr: string) {
      const stringObj = columnStr.split(' ');
      if (stringObj.length == 2) {
        return stringObj[1].length == 1 ? 'no-wrap-text' : '';
      }

      return '';
    },

    displayName(columnName: string, rowId: any) {
      // logInfo('displayName', columnName, rowId);
      try {
        logInfo(this.lineDataObj[rowId]['columns'][columnName].content);
      } catch (error) {
        logError('displayName', columnName, this.lineDataObj[rowId]['columns']);
      }
      return columnName;
    },

    confirmRequestReformate() {
      if (
        this.record.po_multi_matched &&
        this.record.po_multi_matched.length > 0
      ) {
        this.confirmReformate = true;
        return;
      }

      this.requestReformate();
    },

    proceedToReformat() {
      this.confirmReformate = false;
      this.record.po_multi_matched = [];
      this.requestReformate();
    },

    async requestReformate(restore_table_columns = false) {
      try {
        if (this.isReadOnly) {
          return;
        }
        // DOCB-11039: acquire the doc lock before writing, same as
        // saveRules/deleteRules below. Table Tags Apply used to write
        // straight to the backend without going through the doc-lock flow,
        // so this session's own change was never tagged against the current
        // lock/version — leaving the locally cached document_version stale
        // and prone to a spurious "document already modified" conflict
        // against itself on the next lock check.
        const actionLockAcquired = await this.hasActionAcquiredLock();
        if (!actionLockAcquired) {
          return;
        }
        this.lineItemsloading = true;
        this.resetRows();
        const data = {
          doc_id: this.record.doc_id,
          data: JSON.stringify(this.getTableData()),
          column_mapping_indexes: JSON.stringify(
            this.getColumnMappingIndexes(),
          ),
          ai_prompt: this.ai_prompt ? this.ai_prompt : '',
          ai_tags: JSON.stringify(this.ai_tags),
          columns_to_hide: this.getColumnToHide(),
          column_origins: JSON.stringify(this.getColumnOrigins()),
          extract_from: JSON.stringify(this.getExtractOrigins()),
        } as dynamicObj;

        if (restore_table_columns) {
          data['restore_table_columns'] = true.toString();
        }

        if (this.record.hasOwnProperty('is_table_training_doc')) {
          data['is_table_training_doc'] = true.toString();
        }

        const response = await aiTableApiService.reformatAITable(data);
        if (response.success === false) {
          throw response.message;
        }
        this.setTableData(response);
        this.refactorApiData();
        this.dispatchEventToSaveTableChanges();
        this.lineItemsloading = false;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    getExtractOrigins() {
      return this.tableObj.formatting_options.extract_from as dynamicObj;
    },

    setDataForRuleSave() {
      this.tableObj.ai_tags = this.ai_tags;
      this.tableObj.ai_prompt = this.ai_prompt;
      this.record.tables[0] = this.tableObj;
    },

    async saveRules() {
      try {
        if (this.isReadOnly) {
          return;
        }
        const actionLockAcquired = await this.hasActionAcquiredLock();
        if (!actionLockAcquired) {
          return;
        }
        this.showLoading();
        this.setDataForRuleSave();
        const data = {
          data: JSON.stringify(this.record),
        } as dynamicObj;

        const response = await aiTableApiService.saveRules(data);
        if (response.success === false) {
          throw { message: response.message };
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async deleteRules() {
      try {
        if (this.isReadOnly) {
          return;
        }
        const actionLockAcquired = await this.hasActionAcquiredLock();
        if (!actionLockAcquired) {
          return;
        }
        this.showLoading();
        this.setDataForRuleSave();
        const data = {
          doc_id: this.record.doc_id,
        } as dynamicObj;

        const response = await aiTableApiService.deleteRules(data);
        if (response.success === false) {
          throw response.message;
        }
        notify.success(
          this.$t('RULES_DELETED_SUCESSFULLY'),
        );
        await this.autoDetectTables({
          extract_ai_table: true.toString(),
        });

        this.tableObj = this.record.tables[0];
        this.lineItemDataLoaded();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    highlightRow(id: string) {
      const event = new CustomEvent('highlight_table_row', {
        detail: tableRowIdPreFix + id,
      });
      document.dispatchEvent(event);
    },

    reRenderTable() {
      this.displayTable = false;

      if (
        this.tableRows.length > 0 &&
        (!this.record.hasOwnProperty('tables') ||
          isUndefinedOrNull(this.record.tables) ||
          this.record.tables.length == 0)
      ) {
        this.deleteTable();
        return;
      }

      this.init();
    },
    renderShowMapCoulums() {
      this.refactorApiData();
    },
    addTages(val: string, done: any) {
      done({
        label: val,
        value: val,
      });
    },

    aiTagsUpdate(current_ai_tags: dynamicObj[]) {
      if (!current_ai_tags) {
        return;
      }
      current_ai_tags.forEach((tag: dynamicObj) => {
        if (tag.new_tag) {
          tag.label = tag.label.replace(' (' + this.$t('new') + ' tag)', '');
        }
      });

      this.tags_filtered_options = this.getUniqueTags(current_ai_tags);
      if (this.$refs.ai_tags_ref !== void 0) {
        (this.$refs.ai_tags_ref as any).refresh();
        (this.$refs.ai_tags_ref as any).updateInputValue('');
      }
    },

    getUniqueTags(current_ai_tags: dynamicObj[]) {
      if (!current_ai_tags) {
        return [];
      }
      const selectedValues = current_ai_tags.map(
        (tag: dynamicObj) => tag.value as string,
      );
      const uniqueTags = this.tags_options.filter(
        (tag: dynamicObj) => !selectedValues.includes(tag.value),
      );
      return uniqueTags as dynamicObj[];
    },

    filterTagList(val: string, update: any, abort: any) {
      const uniqueTags = this.getUniqueTags(this.ai_tags);

      if (val === '') {
        update(() => {
          this.tags_filtered_options = uniqueTags;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.tags_filtered_options = uniqueTags.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );

        if (this.tags_filtered_options.length === 0) {
          this.tags_filtered_options.push({
            label: needle + ' (' + this.$t('new') + ' tag)',
            value: needle,
            new_tag: true,
          });
        }
      });
    },

    displayNonMappedColumnsDialog() {
      this.nonMappedColumnsDialog = true;
    },

    addNonMappedColumns(e: any) {
      this.nonMappedColumnsDialog = false;
      if (
        !e ||
        !e.detail ||
        !e.detail.hasOwnProperty('columns_in_table') ||
        !e.detail.columns_in_table
      ) {
        return;
      }

      try {
        const columns_in_table = e.detail.columns_in_table;

        const row = this.tableObj.rows[0];
        if (!row) {
          return;
        }

        const existing_columns = {} as dynamicObj;
        const new_columns = {} as dynamicObj;

        for (let [index, item] of Object.entries(this.tableColumns)) {
          const column = item as dynamicObj;
          if (
            column.hasOwnProperty('is_extra_column') &&
            column.is_extra_column === true
          ) {
            existing_columns[column.name] = column;
          }
        }

        for (let [index, item] of Object.entries(columns_in_table)) {
          const column = item as dynamicObj;
          if (!existing_columns.hasOwnProperty(column.column_name)) {
            new_columns[index] = index;
          }
        }

        // columns which are removed from list
        const removed_columns = {} as dynamicObj;
        for (let [index, item] of Object.entries(existing_columns)) {
          const column = item as dynamicObj;

          if (
            !columns_in_table.hasOwnProperty(column.name) &&
            column.hasOwnProperty('is_extra_column') &&
            column.is_extra_column === true
          ) {
            removed_columns[column.name] = column.name;
          }
        }

        if (objLen(new_columns) == 0 && objLen(removed_columns) == 0) {
          return;
        }

        Array.from(this.tableObj.rows).forEach((row: any, rowIndex: any) => {
          for (let [index, item] of Object.entries(removed_columns)) {
            const col_index = this.tableObj.rows[rowIndex].columns.findIndex(
              (obj: dynamicObj) => obj.name === index,
            );
            this.tableObj.rows[rowIndex].columns.splice(col_index, 1);
          }

          for (let [index, item] of Object.entries(columns_in_table)) {
            const column = item as dynamicObj;
            if (existing_columns.hasOwnProperty(column.column_name)) {
              continue;
            }

            column.org_index = '';
            let columObj = {
              name: column.column_name,
              value: '',
              content: '',
              locations: [],
              locations_list: [],
              formatted_value: '',
              is_extra_column: true,
            };
            this.tableObj.rows[rowIndex].columns.push(columObj);
          }
        });

        // Remove added columns from the custom_columns_to_hide array
        for (let [index, item] of Object.entries(columns_in_table)) {
          const column = item as dynamicObj;
          const hideIndex = this.custom_columns_to_hide.indexOf(
            column.column_name,
          );
          if (hideIndex !== -1) {
            this.custom_columns_to_hide.splice(hideIndex, 1);
          }
        }

        // Update formatting_options to persist the change
        if (this.tableObj.formatting_options) {
          this.tableObj.formatting_options.custom_columns_to_hide =
            this.custom_columns_to_hide;
        }

        this.dispatchEventToSaveTableChanges();
        this.reRenderTable();
      } catch (error) {
        logError(error);
      }
      // lineItemLayout
    },

    focusFirstRowColumn(e: any) {
      if (this.tableRows.length === 0) {
        return;
      }
      const first_row = this.tableRows[0];
      if (!first_row) {
        return;
      }
      const first_column = this.tableColumns[1];
      if (!first_column) {
        return;
      }
      this.focusOnColumn(first_column.name);
    },
    focusOnColumn(col_name: string) {
      const firstField: HTMLElement | null = document.querySelector(
        '[data-column-name="' + col_name + '"]',
      );
      if (!firstField) {
        return;
      }
      firstField.click();
      firstField.focus();
    },
  },
  setup() {
    const docStore = useDocumentStore();

    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode, formBuilderModel } =
      storeToRefs(form_builder_store);

    const doc_line_items_store = useLineItemStore();
    const { validation_done, missing_mapping_column, lineDataObj, tableRows } =
      storeToRefs(doc_line_items_store);

    const doc_store = useDocumentStore();
    const {
      record,
      doc_loaded,
      has_ai_table,
      remove_unmapped_columns,
      is_extracted_table_update,
    } = storeToRefs(doc_store);
    const { saveDocument, autoDetectTables } = doc_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock } = doc_lock_store;

    let data: any = [];
    let model = {} as { [k: string]: any };
    const filter = ref('');

    return {
      remove_unmapped_columns,
      formBuilderModel,
      has_ai_table,
      saveDocument,
      autoDetectTables,
      is_extracted_table_update,
      startSettingsFetch,
      hasActionAcquiredLock,
      setting_flag: ref(false),
      user_settings,
      loading_settings,
      record,
      doc_loaded,
      is_line_item_validated: validation_done,
      missing_mapping_column,
      filter,
      docStore,
      headers: ref(),
      lineitems: ref(),
      move_extra_rows_to: ref(''),
      header_rows_count: ref(1),
      min_group_rows: ref(1),
      max_group_rows: ref(),
      distinct_group_column: ref(false),
      reverse_grouping: ref(false),
      group_column: ref(''),
      column_mapping_indexes: ref(model),
      columns_to_hide: ref(data),
      custom_columns_to_hide: ref(data),
      addFieldsDialog: ref(false),
      extra_columns: ref(data),
      poEditRestrictDialog: ref(false),
      poEditRestrictMessage: ref(''),
      new_field_model: ref(model),
      new_column_model: ref(model),
      revert_changes_confirm_dialog: ref(false),
      adv_column_options: data,
      advance_settings_columns: ref([] as any),
      confirmDialog: ref(false),
      displayTable: ref(false),
      selectedColumn: ref(''),
      showRegexDlg: ref(false),
      openAdvSettings: ref(false),
      oldSelectedColumnName: ref(''),
      showConfirmDeleteColumn: ref(false),
      show_confirm_remap_dialog: ref(false),
      pending_column_remap: ref(null as any),
      headerRowCountRules: [
        (val: number) => val !== null || 'Please type number',
        (val: number) => (val > 0 && val < 100) || 'Please type number',
      ],

      showNotification(message: string) {
        notify.info(message);
      },

      // apiData: ref(data),
      lineDataObj,
      lineItemsErrorsRaw: ref({} as dynamicObj),
      lineItemLayout: ref(data),
      tableColumns: ref(data),
      uniqueColumns: ref(new Set()), // it will contains all valid columns names.
      tableRows,
      formatting_options: ref(model),
      addColumnDialog: ref(false),
      headerKey: ref(''),
      headerLable: ref(''),
      lineItemsloading: ref(true),
      openDisableColumnListView: ref(false),
      disableColumnList: ref(data),
      split_text: ref(false),
      split_text_confirm_dialog: ref(false),
      tableRowsLocationsMap: ref(new Map()), //this map will contain only first row of all the pages
      layoutExtraColumns: ref([] as any),
      isFormBuilderMode,
      ai_prompt: ref(''),
      ai_tags: ref([] as any),
      tags_options: ref([] as any),
      tags_filtered_options: ref([] as any),
      nonMappedColumnsDialog: ref(false),
    };
  },
});
</script>
