<template>
  <q-card style="width: 900px; max-width: 1060px">
    <q-toolbar class="text-white secondary-toolbar draggable-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('column_settings') }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section>
      <!-- Main -->
      <div>
        <div class="row no-wrap justify-around q-pt-md">
          <!-- Visible list -->

          <div class="drop-target rounded-borders q-mr-md">
            <div
              class="box row justify-center items-center"
              style="border-bottom: 1px solid grey"
            >
              {{ $t('available_columns') }}
            </div>

            <div class="visible-doc-columns-parent">
              <template v-for="(row, index) in available_columns" :key="index">
                <div draggable="true" class="draggable-box row full-width">
                  <div
                    draggable="true"
                    :id="row.name"
                    :data-column-name="row.name"
                    class="box"
                  >
                    <q-checkbox
                      :data-column-name="row.name"
                      v-model="row.selected"
                      class="box-checkbox"
                      :label="row.lbl_to_display"
                    />
                  </div>
                </div>
              </template>
            </div>
          </div>

          <!-- middle buttons -->
          <div class="rounded-borders overflow-hidden content-center">
            <div class="row justify-end items-start">
              <f-btn
                class="q-mr-md mt-20"
                icon="arrow_forward"
                @click="moveToTableColumnList"
              >
                <q-tooltip>{{
                  $t('move_to_visibile_button_tooltip')
                }}</q-tooltip>
              </f-btn>
            </div>

            <div class="row justify-end items-start">
              <f-btn
                class="q-mr-md mt-20"
                icon="arrow_back"
                @click="moveToAvailableColumnList"
              >
                <q-tooltip>
                  {{ $t('move_to_hidden_button_tooltip') }}
                </q-tooltip>
              </f-btn>
            </div>
          </div>

          <!-- hidden list -->
          <div class="drop-target rounded-borders">
            <div
              class="box row justify-center items-center"
              style="border-bottom: 1px solid grey"
            >
              {{ $t('columns_in_table') }}
            </div>
            <template v-for="(row, index) in columns_in_table" :key="index">
              <div
                :id="row.name"
                :data-column-name="row.name"
                class="box row full-width"
              >
                <q-checkbox
                  :data-column-name="row.name"
                  v-model="row.selected"
                  :label="row.lbl_to_display"
                />
              </div>
            </template>
          </div>
        </div>

        <div class="row justify-end items-start q-mt-md">
          <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

          <f-btn :label="$t('done')" class="q-ml-sm" @click="saveSettings()" />
        </div>
      </div>
    </q-card-section>

    <q-inner-loading :showing="processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
// @ts-nocheck
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  props: {
    lineItemLayout: {
      type: Object,
    },
    tableColumns: {
      type: Array,
    },
  },
  components: {},
  mounted() {
    this.init();
  },
  data() {
    return {
      dragSrcEl: {} as any,
      clearInterval: 0 as any,
    };
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    // Before leaving this page, lets first reset everything
    next();
  },
  methods: {
    init() {
      this.available_columns = {} as dynamicObj;
      this.columns_in_table = {} as dynamicObj;

      this.setColumns();
    },

    setColumns() {
      this.all_columns = JSON.parse(JSON.stringify(this.lineItemLayout));
      let available_columns = JSON.parse(
        JSON.stringify(this.lineItemLayout),
      ) as dynamicObj;

      for (const key in this.tableColumns) {
        const index = Number(key);
        const item = this.tableColumns[index] as dynamicObj;

        if (!available_columns[item.name]) {
          continue;
        }

        if (item.name == 'id') {
          delete available_columns[item.name];
          continue;
        }

        const column = Object.assign(available_columns[item.name], {
          selected: false,
        });

        if (item.is_extra_column) {
          this.columns_in_table[item.name] = JSON.parse(JSON.stringify(column));
          delete available_columns[item.name];
          continue;
        }

        if (item.org_index != null && item.org_index != undefined) {
          delete available_columns[item.name];
          continue;
        }
      }

      this.available_columns = available_columns;
      this.setAvailableColumnsCheckbox();
    },

    setAvailableColumnsCheckbox() {
      for (const [index, item] of Object.entries(this.available_columns)) {
        const column = Object.assign(item, { selected: false });
        this.available_columns[index] = column;
      }
    },

    moveToTableColumnList() {
      for (const [index, item] of Object.entries(this.available_columns)) {
        logInfo(item.name, item.selected);
        if (!item.selected) {
          continue;
        }
        item.selected = false;

        const column = JSON.parse(JSON.stringify(item));
        column.from_layout = true;
        this.columns_in_table[index] = JSON.parse(JSON.stringify(column));
        delete this.available_columns[index];
      }
    },

    moveToAvailableColumnList() {
      for (var key of Object.keys(this.columns_in_table)) {
        if (!this.columns_in_table[key].selected) {
          continue;
        }
        this.columns_in_table[key].selected = false;
        this.available_columns[key] = this.columns_in_table[key];
        delete this.columns_in_table[key];
      }
      this.setAvailableColumnsCheckbox();
    },

    saveSettings() {
      this.processing = true;
      const event = new CustomEvent('add_non_mapped_columns', {
        detail: {
          columns_in_table: this.columns_in_table,
        },
      });
      document.dispatchEvent(event);
    },
  },
  setup() {
    return {
      available_columns: ref({} as dynamicObj),
      columns_in_table: ref({} as any),
      processing: ref(false),
      all_columns: ref({} as dynamicObj),
      show_column_settings: ref(false),
    };
  },
});
</script>
